func s2LessMethod[T interface{ Less(T) bool }](x, y T) (T, T) {
	if y.Less(x) {
		return y, x
	}
	return x, y
}

func heapSortLessMethod[T interface{ Less(T) bool }](a []T) {
	n := len(a)
	if n < 2 {
		return
	}
	for i := n / 2; ; {
		var k T
		if i > 0 {
			i--
			k = a[i]
		} else {
			n--
			if n == 0 {
				return
			}
			k = a[n]
			a[n] = a[0]
		}
		j := i
		for j*2+1 < n {
			child := j*2 + 1
			if child+1 < n && (a[child].Less(a[child+1])) {
				child++
			}
			if !(k.Less(a[child])) {
				break
			}
			a[j] = a[child]
			j = child
		}
		a[j] = k
	}
}

